from pptx import Presentation

prs = Presentation("deck.pptx")
slide = prs.slides[2]
left = right = None
for shape in slide.shapes:
    if "-left-" in shape.name:
        left = shape
    elif "-right-" in shape.name:
        right = shape
if left is not None and right is not None:
    for paragraph in right.text_frame.paragraphs:
        # Carry the paragraph over whole, so its runs keep their own formatting.
        left.text_frame._txBody.append(paragraph._p)
    right._element.getparent().remove(right._element)
prs.save("deck.pptx")

